@Override public ImmutableList<String> getSupportedSampleMimeTypes(@C.TrackType int trackType, String containerMimeType) {
  if (trackType == C.TRACK_TYPE_VIDEO) {
    return SUPPORTED_CONTAINER_TO_VIDEO_SAMPLE_MIME_TYPES.getOrDefault(containerMimeType, ImmutableList.of());
  } else if (trackType == C.TRACK_TYPE_AUDIO) {
    return SUPPORTED_CONTAINER_TO_AUDIO_SAMPLE_MIME_TYPES.getOrDefault(containerMimeType, ImmutableList.of());
  }
  return ImmutableList.of();
}
